//! The command-running check kinds: `tests_pass`, `coverage_min`,
//! `lint_clean`, `complexity_clean`, `--partial`, `--no-run`, and the
//! `degraded` flag.
//!
//! Every fake command is `exit 0` or `exit 1`, which both `cmd.exe /C` and
//! `/bin/sh -c` accept, so no fixture needs a script file or a shebang. Every
//! coverage artifact is written from Rust rather than generated by a command.

mod common;

use assert_cmd::Command;
use common::Project;
use devforgeai::config::{Config, Stack};

fn cli(p: &Project) -> Command {
    let mut c = Command::cargo_bin("devforgeai").expect("the binary builds");
    c.arg("--project").arg(p.root());
    c.current_dir(p.root());
    c
}

fn gate(p: &Project, args: &[&str]) -> (i32, String, String) {
    let out = cli(p)
        .args(["gate", "check", "--phase", "build", "--id", "STORY-014"])
        .args(args)
        .output()
        .expect("run");
    (
        out.status.code().unwrap_or(-1),
        String::from_utf8_lossy(&out.stdout).to_string(),
        String::from_utf8_lossy(&out.stderr).to_string(),
    )
}

fn gate_json(p: &Project, args: &[&str]) -> serde_json::Value {
    let out = cli(p)
        .args([
            "--json",
            "gate",
            "check",
            "--phase",
            "build",
            "--id",
            "STORY-014",
        ])
        .args(args)
        .output()
        .expect("run");
    let text = String::from_utf8_lossy(&out.stdout).to_string();
    serde_json::from_str(text.trim()).unwrap_or_else(|e| panic!("{e} in {text}"))
}

/// The build gate, with the three required kinds plus whatever `extra` adds.
fn gates(extra: &str) -> String {
    format!(
        r#"schema = "devforgeai/gates/1"
cli_min_version = "1.0.0"

[[gate]]
phase = "build"
requires = ""
on_fail = "fail"

  [[gate.check]]
  kind = "doc_valid"
  id = "build-docs"
  docs = ["stories/STORY-014.md"]

  [[gate.check]]
  kind = "tests_pass"
  id = "build-tests"

  [[gate.check]]
  kind = "coverage_min"
  id = "build-coverage"
  source = "read"

{extra}"#
    )
}

/// A `[[stack]]` whose four commands are the fakes the test wants.
fn stack(test: &str, coverage: &str, lint: &str, complexity: &str) -> Stack {
    Stack {
        id: "rust".into(),
        markers: vec!["Cargo.toml".into()],
        package_manager: "cargo".into(),
        source_roots: vec!["src".into()],
        test_command: test.into(),
        coverage_command: coverage.into(),
        lint_command: lint.into(),
        complexity_command: complexity.into(),
        coverage_format: "lcov".into(),
        coverage_paths: vec!["cov/lcov.info".into()],
        timeout_secs: 60,
        ..Default::default()
    }
}

/// An lcov artifact: one domain file and one interface file.
const LCOV: &str = "TN:\nSF:src/domain/order.rs\nDA:1,1\nDA:2,1\nDA:3,1\nDA:4,1\nDA:5,1\nDA:6,1\nDA:7,1\nDA:8,1\nDA:9,1\nDA:10,1\nend_of_record\nSF:src/api/http.rs\nDA:1,1\nDA:2,1\nDA:3,1\nDA:4,1\nDA:5,1\nDA:6,1\nDA:7,1\nDA:8,0\nDA:9,0\nDA:10,0\nend_of_record\n";

fn seeded(s: Stack, extra: &str) -> Project {
    let p = Project::new();
    p.write(
        ".devforgeai/stories/STORY-014.md",
        &common::story("STORY-014", "building", &[], "# Order checkout\n"),
    );
    p.write(".devforgeai/gates.toml", &gates(extra));
    p.write("cov/lcov.info", LCOV);
    let degraded = s.id.is_empty();
    p.write_config(&Config {
        degraded,
        stack: if degraded { vec![] } else { vec![s] },
        generated_at: "2026-09-10T14:02:11Z".into(),
        ..Default::default()
    });
    p.set_phase("build", "STORY-014");
    p
}

fn status_of(v: &serde_json::Value, id: &str) -> String {
    v["data"]["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .find(|c| c["id"] == id)
        .unwrap_or_else(|| panic!("check {id} in {v}"))["status"]
        .as_str()
        .unwrap_or("")
        .to_string()
}

fn reason_of(v: &serde_json::Value, id: &str) -> String {
    v["data"]["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .find(|c| c["id"] == id)
        .unwrap_or_else(|| panic!("check {id} in {v}"))["reason"]
        .as_str()
        .unwrap_or("")
        .to_string()
}

// ------------------------------------------------------------- tests_pass

#[test]
fn a_test_command_that_exits_zero_passes() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-tests"), "pass", "{v}");
}

#[test]
fn a_test_command_that_exits_one_fails_with_e311() {
    let p = seeded(stack("exit 1", "exit 0", "", ""), "");
    let (code, _, _) = gate(&p, &[]);
    assert_eq!(code, 1);
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-tests"), "fail");
    assert!(reason_of(&v, "build-tests").contains("DFA-E311"), "{v}");
}

#[test]
fn an_empty_test_command_fails_with_e310_when_the_stack_is_detected() {
    let p = seeded(stack("", "exit 0", "", ""), "");
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-tests"), "fail");
    assert!(reason_of(&v, "build-tests").contains("DFA-E310"), "{v}");
}

#[test]
fn allow_empty_lets_an_empty_test_command_pass() {
    let p = seeded(
        stack("", "exit 0", "", ""),
        "  [[gate.check]]\n  kind = \"tests_pass\"\n  id = \"build-tests-2\"\n  allow_empty = true\n",
    );
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-tests-2"), "pass", "{v}");
}

#[test]
fn the_evidence_carries_the_command_the_code_and_the_counts() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    let v = gate_json(&p, &[]);
    let e = &v["data"]["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .find(|c| c["id"] == "build-tests")
        .expect("the check")["evidence"];
    assert_eq!(e["command"], "exit 0");
    assert_eq!(e["exit_code"], 0);
    assert!(e["duration_ms"].is_number(), "{e}");
    assert!(e["output_tail"].is_string(), "{e}");
    assert!(
        e["passed"].is_null(),
        "an unmatched pattern leaves the count null, not zero: {e}"
    );
}

#[test]
fn the_stacks_key_narrows_the_run() {
    let p = seeded(
        stack("exit 1", "exit 0", "", ""),
        "  [[gate.check]]\n  kind = \"tests_pass\"\n  id = \"build-tests-node\"\n  stacks = [\"node\"]\n",
    );
    let v = gate_json(&p, &[]);
    // A check that names a stack the project does not hold has nothing to run
    // and therefore nothing to prove. Passing it is the free pass: the gate
    // would report a green `tests_pass` for a test suite that never ran.
    assert_eq!(
        status_of(&v, "build-tests-node"),
        "fail",
        "a check whose named stack is absent fails rather than passing: {v}"
    );
    let reason = reason_of(&v, "build-tests-node");
    assert!(reason.contains("DFA-E310"), "{reason}");
    assert!(
        reason.contains("node"),
        "the absent stack is named: {reason}"
    );
}

