// ------------------------------------------------------------ coverage_min

#[test]
fn coverage_min_reads_the_artifact_and_fills_the_report_block() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    let v = gate_json(&p, &[]);
    // domain 10/10 = 100.0, interface 7/10 = 70.0, overall 17/20 = 85.0.
    let c = &v["data"]["coverage"];
    assert_eq!(c["format"], "lcov");
    assert_eq!(c["source"], "cov/lcov.info");
    assert_eq!(c["overall"], 85.0, "{c}");
    let domain = c["layers"]
        .as_array()
        .expect("layers")
        .iter()
        .find(|l| l["name"] == "domain")
        .expect("domain");
    assert_eq!(domain["covered"], 10);
    assert_eq!(domain["total"], 10);
    assert_eq!(domain["percent"], 100.0);
    assert_eq!(domain["min"], 95.0);
    assert_eq!(domain["status"], "pass");

    let report = p.read(".devforgeai/reports/STORY-014-build.yaml");
    assert!(report.contains("coverage:"), "report was {report}");
    assert!(report.contains("overall: 85"), "report was {report}");
}

#[test]
fn a_layer_below_its_threshold_fails_with_e313() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    // interface is 70.0 against the 70.0 default, so raise it.
    let mut cfg = devforgeai::config::load(p.root()).expect("config");
    for l in cfg.layer.iter_mut() {
        if l.name == "interface" {
            l.coverage_min = 90.0;
        }
    }
    p.write_config(&cfg);
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-coverage"), "fail");
    let reason = reason_of(&v, "build-coverage");
    assert!(reason.contains("DFA-E313"), "{reason}");
    assert!(reason.contains("interface"), "{reason}");
    assert!(reason.contains("70"), "{reason}");
}

#[test]
fn the_layers_key_narrows_the_check() {
    let p = seeded(
        stack("exit 0", "exit 0", "", ""),
        "  [[gate.check]]\n  kind = \"coverage_min\"\n  id = \"domain-only\"\n  source = \"read\"\n  layers = [\"domain\"]\n  overall = false\n",
    );
    let mut cfg = devforgeai::config::load(p.root()).expect("config");
    for l in cfg.layer.iter_mut() {
        if l.name == "interface" {
            l.coverage_min = 90.0;
        }
    }
    p.write_config(&cfg);
    let v = gate_json(&p, &[]);
    assert_eq!(
        status_of(&v, "domain-only"),
        "pass",
        "the interface shortfall is outside the named set: {v}"
    );
}

#[test]
fn the_overall_figure_is_checked_against_its_own_floor() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    let mut cfg = devforgeai::config::load(p.root()).expect("config");
    cfg.coverage.overall_min = 90.0;
    p.write_config(&cfg);
    let v = gate_json(&p, &[]);
    let reason = reason_of(&v, "build-coverage");
    assert!(reason.contains("DFA-E313"), "{reason}");
    assert!(reason.contains("overall"), "{reason}");
}

