#[test]
fn an_excluded_file_is_dropped_before_the_figures() {
    let p = seeded(stack("exit 0", "exit 0", "", ""), "");
    p.write(
        "cov/lcov.info",
        &format!("{LCOV}SF:src/tests/helper.rs\nDA:1,0\nDA:2,0\nend_of_record\n"),
    );
    let v = gate_json(&p, &[]);
    assert_eq!(
        v["data"]["coverage"]["overall"], 85.0,
        "the excluded file changed nothing: {}",
        v["data"]["coverage"]
    );
}

// ---------------------------------------------------------------- degraded

#[test]
fn a_degraded_project_skips_every_command_kind() {
    let mut s = stack("", "", "", "");
    s.id = String::new();
    let p = seeded(
        s,
        "  [[gate.check]]\n  kind = \"lint_clean\"\n  id = \"build-lint\"\n",
    );
    let v = gate_json(&p, &[]);
    assert_eq!(v["data"]["degraded"], true);
    for id in ["build-tests", "build-coverage", "build-lint"] {
        assert_eq!(status_of(&v, id), "skip", "{id}: {v}");
        assert_eq!(reason_of(&v, id), "degraded", "{id}");
    }
    assert_eq!(v["exit"], 0, "a skip counts as passing");

    // The degradation rule puts one line on stderr whenever the flag is set.
    let (_, _, err) = gate(&p, &[]);
    assert!(
        err.contains("Stack undetected; command checks skipped."),
        "stderr was {err}"
    );
}

#[test]
fn a_degraded_project_keeps_the_document_check() {
    let mut s = stack("", "", "", "");
    s.id = String::new();
    let p = seeded(s, "");
    let v = gate_json(&p, &[]);
    assert_eq!(status_of(&v, "build-docs"), "pass", "{v}");
}

// ----------------------------------------------------------------- --no-run

#[test]
fn no_run_skips_the_three_command_kinds_and_reads_coverage() {
    let p = seeded(
        stack("exit 1", "exit 1", "exit 1", "exit 1"),
        "  [[gate.check]]\n  kind = \"lint_clean\"\n  id = \"build-lint\"\n\n  [[gate.check]]\n  kind = \"complexity_clean\"\n  id = \"build-complexity\"\n",
    );
    let v = gate_json(&p, &["--no-run"]);
    for id in ["build-tests", "build-lint", "build-complexity"] {
        assert_eq!(status_of(&v, id), "skip", "{id}: {v}");
        assert_eq!(reason_of(&v, id), "no_run", "{id}");
    }
    assert_eq!(
        status_of(&v, "build-coverage"),
        "pass",
        "coverage still parses the file on disk: {v}"
    );
}

// ---------------------------------------------------------------- --partial

#[test]
fn partial_evaluates_only_the_four_command_kinds() {
    let p = seeded(
        stack("exit 0", "exit 0", "", ""),
        "  [[gate.check]]\n  kind = \"lint_clean\"\n  id = \"build-lint\"\n\n  [[gate.check]]\n  kind = \"complexity_clean\"\n  id = \"build-complexity\"\n",
    );
    let v = gate_json(&p, &["--partial"]);
    let ids: Vec<String> = v["data"]["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .map(|c| c["id"].as_str().unwrap_or("").to_string())
        .collect();
    assert_eq!(
        ids,
        vec![
            "build-tests".to_string(),
            "build-coverage".to_string(),
            "build-lint".to_string(),
            "build-complexity".to_string()
        ],
        "the document check is not evaluated"
    );
    assert_eq!(v["data"]["partial"], true);
}

#[test]
fn partial_exits_zero_whatever_the_result_and_leaves_state_alone() {
    let p = seeded(stack("exit 1", "exit 0", "", ""), "");
    let before = p.state().last_gate.result.clone();
    let (code, _, _) = gate(&p, &["--partial"]);
    assert_eq!(code, 0, "--partial exits 0 whatever the result");
    let v = gate_json(&p, &["--partial"]);
    assert_eq!(status_of(&v, "build-tests"), "fail");
    assert_eq!(
        p.state().last_gate.result,
        before,
        "state.toml is untouched"
    );

    let report = p.read(".devforgeai/reports/STORY-014-build.yaml");
    assert!(report.contains("partial: true"), "report was {report}");
}
